__NUXT_JSONP__("/kr/price-v2", (function(a,b,c,d,e,f,g,h,i,j,k,l){return {data:[{details:{slug:b,pageTitle:"가격 | Mentor Language Institute",pageDescription:"만약 저희 학교에서 제공하는 숙박 시설이 필요 없을 경우에는 ②숙박비를 지불하실 필요가 없습니다.",title:"가격",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fkr\u002Fprice-auto\"\u003E가격 계산기\u003C\u002Fa\u003E"]}]},steps:{title:"①학비＋②숙박비＋③기타 비용",subtitle:["만약 저희 학교에서 제공하는 숙박 시설이 필요 없을 경우에는 ②숙박비를 지불하실 필요가 없습니다.\u003Cbr\u003E* \u003Ca href=\"\u002Fkr\u002Fprice-auto\u002F\"\u003E가격 계산기\u003C\u002Fa\u003E 를 사용하세요."],lists:[{title:"①학비",subtitle:["가격은 프로그램과 등록 기간에 따라 변경 됩니다.\u003Cbr \u002F\u003E 더 많은 기간을 등록할수록, 더 많은 할인을 받으실 수 있습니다."],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",description:["\u003Cb\u003EQ&A\u003C\u002Fb\u003E","\u003Cb\u003EQ:\u003C\u002Fb\u003E  학교를 시작한 후에 프로그램을 변경 할 수 있나요? \u003Cbr \u002F\u003E\u003Cb\u003EA:\u003C\u002Fb\u003E  예, 할 수 있습니다!"]},{title:"②숙박비",subtitle:["우리는 학생들에게 홈스테이, 기숙사를 제공합니다.미국 문화를 경험하고 싶은 학생에게는 홈스테이를 추천하고 많은 친구들을 만나고 싶은 학생들에게는 기숙사를 추천합니다."],category:[{title:"홈스테이 가격",table:{tableMaxCol:3,title:"배치 수수료* : $300\u003Cbr \u002F\u003E 18세 미만인 경우 임대료는 18세 이상인 사람의 가격보다 약 10% 더 높습니다.",thead:[c,d,"Shared(2인실)***"],tbody:[[e,a,a],[f,"$436","$384"],[g,"$872","$768"],[h,"$1,308","$1,152"],[i,"$1,744","$1,536"],[j,"$3,160","$2,904"],[k,"$4,740","$4,356"]]}},{title:"기숙사 가격",table:{tableMaxCol:4,title:"배치수수료* : $200\u003Cbr \u002F\u003E 18세 미만인 경우 임대료는 18세 이상인 사람의 가격보다 약 10% 더 높습니다.",thead:[c,d,"Shared(2인실)","Quad(4인실)"],tbody:[[e,a,a,a],[f,"$550","$410",a],[g,"$1,100","$820","$600"],[h,"$1,650","$1,230","$900"],[i,"$2,200","$1,640","$1,200"],[j,"$4,160","$2,960","$2,160"],[k,"$6,240","$4,440","$3,240"]]},description:["*배치 수수료는 한 번만 지불 하시면 되나 환불은 안됩니다.\u003Cbr \u002F\u003E**보증금은 학생들이 퇴거후에 환불 됩니다.\u003Cbr \u002F\u003E***만약 Shared(2인실)을 신청했을 경우에는, \u003Cspan class=\"rmarker\"\u003E 반드시 다른 학생과 같이 방을 사용해야합니다. \u003C\u002Fspan\u003E","※숙박 서비스는 U.S. Support Service 또는 다른 에이전트로부터 제공됩니다.","\u003Ca href=\"\u002Fkr\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E  숙박에 대한 더 많은 정보\u003C\u002Fa\u003E"]}]},{title:"③ 초기 지불액",subtitle:["위에 명시된 요금 외에 등록시 지불해야 될 요금이 있습니다."],lists:[l,"I-20 배송비**: $120","SEVIS 요금**: $350(SEVP에 바로 지불 됩니다.)","교과서: $150 - $240"],description:["*환불 안됩니다.\u003Cbr \u002F\u003E** 학생 비자를 신청할 경우에만 적용됩니다."]}]},examples:{title:"예시",subtitle:["가격에 대한 예입니다: 4 주 그리고 48주"],lists:[{title:"1개월(4주)",items:[l,"학비: $1,220","숙박 요금: $1,560（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003E총 금액: $2,930\u003C\u002Fspan\u003E"]},{title:"1년(48주)",items:["초기 지불 금액: $150","학비: $10,032","숙박 요금: $12,360（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003E총 금액: $22,542\u003C\u002Fspan\u003E"]}]},other_info:["금액에 대해서 문의 사항이 있으시면, 언제든지 저희에게 연락주세요."],dir:"\u002Fprice-v2",path:"\u002Fprice-v2\u002Fkr",extension:".json",createdAt:"2026-10-22T16:31:30.518Z",updatedAt:"2026-03-24T13:34:16.697Z"},lang:b}],fetch:{},mutations:void 0}}("$300","kr","","Private(1인실)","\u003Cb\u003E보증금**\u003C\u002Fb\u003E","1 주","2 주","3 주","4 주","8 주","12 주","등록비: $150")));